args.command:
h=a80425fb; awk -v h="$h" 'BEGIN{
  # convert hex to bins
  split("",arr); n=0; val=""; 
  # just print set bits
  c=0;
  # parse hex
  hexchars="0123456789abcdefABCDEF";
  dec=0;
  for(i=1;i<=length(h);i++){ch=substr(h,i,1); for(j=1;j<=16;j++){ch2=substr(hexchars,j,1); if(ch==ch2){dec=dec*16+(j-1); break;}}}
  for(bit=0; bit<64; bit++){ if(and(dec, lshift(1,bit))) printf "%d ",bit}
  print ""
}'

